import json, urllib.request
from playwright.sync_api import sync_playwright
prov=json.load(open('/tmp/prov.json')); B='http://localhost:8765/'; erros=[]; n=0
XLSX=open('/home/claude/testes/node_modules/xlsx/dist/xlsx.full.min.js').read()
def ok(m):
    global n; n+=1; print('ok ',m)
def api(o): return json.loads(urllib.request.urlopen(urllib.request.Request(B+'exec', data=json.dumps(o).encode())).read())
with sync_playwright() as p:
    br=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    ctx=br.new_context(viewport={'width':1366,'height':900}, locale='pt-BR')
    ctx.route('**/cdnjs.cloudflare.com/**/xlsx.full.min.js', lambda rt: rt.fulfill(status=200, content_type='application/javascript', body=XLSX))
    pg=ctx.new_page()
    pg.on('pageerror', lambda e: erros.append('PAGEERR '+str(e)))
    pg.on('console', lambda m: erros.append(m.text) if m.type=='error' and 'ERR_FAILED' not in m.text else None)
    pg.add_init_script("try{localStorage.setItem('jornada_gas_url','http://localhost:8765/exec')}catch(e){}")
    pg.goto(B); pg.fill('#login-email','marques.marcela@estacio.br'); pg.fill('#login-senha',prov['admin']); pg.click('#btn-entrar')
    pg.wait_for_selector('#form-troca:not([hidden])'); pg.fill('#troca-atual',prov['admin']); pg.fill('#troca-nova','Admin2026b'); pg.fill('#troca-conf','Admin2026b'); pg.click('#form-troca button.primario')
    pg.wait_for_function("document.body.dataset.tela==='app'")
    tok=lambda: pg.evaluate("JSON.parse(localStorage.getItem('jornada_sessao')).token")
    pg.goto(B+'#/s/nps'); pg.wait_for_timeout(2500)
    f=[x for x in pg.frames if 'sistema=nps' in x.url][0]
    f.wait_for_selector('#f-importar'); assert 'Nenhuma resposta importada' in f.inner_text('#area'); ok('NPS vazio mostra o botão de importar')
    assert not f.is_visible('#f-arquivo'); ok('campo de arquivo fica escondido (só o botão aparece)')
    assert f.evaluate("getComputedStyle(document.getElementById('bases')).display")=='none'; ok('sem seletor de base Ímpar/Par/Técnico')
    f.set_input_files('#f-arquivo','/home/claude/testes/medallia_ficticio.xlsx'); f.wait_for_function("Motor.estado.alunos.length===8", timeout=20000); ok('importa o arquivo do Medallia (8 respostas)')
    datas=f.evaluate("[...document.querySelectorAll('tbody tr td:nth-child(4)')].map(t=>t.innerText)")
    assert datas[0]=='17/11/26' and datas==sorted(datas,key=lambda d:d[6:]+d[3:5]+d[:2],reverse=True), datas; ok('datas do Excel em dd/mm/aa, mais recente primeiro: '+', '.join(datas[:3]))
    f.select_option('#f-extra','det'); pg.wait_for_timeout(300); assert f.locator('tr[data-mat]').count()==3; ok('filtro de detratores: 3')
    pg.mouse.move(900,400); pg.screenshot(path='/home/claude/testes/tela_nps.png')
    f.locator('tr[data-mat]').first.click(); f.wait_for_selector('#form-ac')
    txt=f.inner_text('#modal-corpo'); assert 'resposta da pesquisa' in txt.lower() and 'Nota\n0' in txt, txt[:300]; ok('ficha mostra a resposta da pesquisa (nota, motivo, comentário, temas)')
    f.select_option('[data-campo=tema]','Infraestrutura'); f.select_option('[data-campo=situacao]','Em tratamento'); f.click('#btn-ficha'); pg.wait_for_timeout(1200)
    f.select_option('#form-ac [name=resultado]','Encaminhado à coordenação'); f.fill('#form-ac [name=obs]','Retorno sobre a internet do prédio'); f.fill('#form-ac [name=fu]','2026-11-25')
    pg.screenshot(path='/home/claude/testes/tela_nps_aluno.png'); f.click('#btn-ac'); pg.wait_for_timeout(1500)
    l=api({'acao':'nps.listar','token':tok()}); assert len(l['regs'])==1 and l['regs'][0]['resultado']=='Encaminhado à coordenação' and list(l['fichas'].values())[0]['dados']['situacao']=='Em tratamento'; ok('acionamento e situação do caso gravados')
    f.click('[data-aba=dashboard]'); pg.wait_for_timeout(400); t=f.inner_text('#area').replace('\xa0',' ')
    assert 'NPS por mês' in t and '0 (meta 46,24)' in t and '3 · 2 · 3' in t, t[:400]; ok('dashboard: NPS 0 (3 promotores, 2 neutros, 3 detratores), por mês e por modalidade')
    pg.mouse.move(900,400); pg.screenshot(path='/home/claude/testes/tela_nps_dash.png', full_page=True)
    f.click('[data-aba=alunos]'); pg.wait_for_timeout(300)
    f.set_input_files('#f-arquivo','/home/claude/testes/medallia_ficticio.xlsx'); pg.wait_for_timeout(4000)
    assert f.evaluate("Motor.estado.alunos.length")==8 and '0 resposta(s) nova(s) e 8 atualizada(s)' in pg.evaluate("document.getElementById('avisos').innerText"); ok('importar de novo não duplica (0 novas, 8 atualizadas)')
    pg.goto(B+'#/bases'); pg.wait_for_selector('.card-sistema.base'); assert '8 respostas' in pg.inner_text('#cards-bases').replace('\xa0',' '); ok('Central de Bases mostra o NPS')
    br.close()
print(n,'passos ok'); print('erros:', erros or 'nenhum')
